/**
 * Pre-built startup roadmaps.
 *
 * These are the ready-made plans someone picks when starting a business —
 * either their first, or another one alongside what they already run. Each is
 * a complete launch checklist with the real Philippine agencies, legal bases,
 * fees and documents, so a user never starts from an empty roadmap.
 *
 * Steps 1-4 of every template are the universal registration path (Barangay →
 * DTI → Mayor → BIR), generated by `registrationSteps()` with the trade's own
 * wording. Only what actually differs by trade is written per template: the
 * equipment, the sourcing, and what opening day requires. Writing the permit
 * steps out seven times would mean seven places to fix when a fee changes.
 */

import { RoadmapTask } from './supabase';

export type TemplateCategory = 'Food & Drinks' | 'Retail' | 'Services' | 'Online' | 'Fashion';

/** Icon drawn on the card banner when a template has no photo. */
export type TemplateIcon =
  | 'coffee'
  | 'store'
  | 'utensils'
  | 'globe'
  | 'scissors'
  | 'shirt'
  | 'paw-print'
  | 'droplets';

export type TemplateTask = Omit<RoadmapTask, 'user_id'>;

export interface StartupTemplate {
  id: string;
  title: string;
  category: TemplateCategory;
  budget: string;
  desc: string;
  /**
   * Optional photo, e.g. require('@/assets/images/templates/milk-tea.jpg').
   * Cards fall back to an accent banner with the icon, so a template without
   * a photo still looks deliberate rather than broken.
   */
  image?: any;
  accent: string;
  icon: TemplateIcon;
  tasks: TemplateTask[];
}

interface RegistrationOptions {
  /** Food handling needs a Sanitary Permit and health cards. */
  sanitary?: boolean;
  /** Home-based online sellers usually skip the Mayor's permit at first. */
  skipMayor?: boolean;
}

/**
 * The four registrations every Philippine micro-business goes through, worded
 * for the trade in question.
 */
const registrationSteps = (
  prefix: string,
  trade: string,
  options: RegistrationOptions = {}
): TemplateTask[] => {
  const steps: TemplateTask[] = [
    {
      title: 'Barangay Micro-Business Clearance',
      category: 'Permits',
      status: 'Pending',
      desc: `Local clearance required before your ${trade} can legally operate.`,
      agency: 'Local Barangay Hall BPLO Desk',
      legal_basis: 'RA 9178 (BMBE Act) & RA 7160 Local Government Code',
      estimated_time: '1 - 2 Business Days',
      estimated_cost: '₱200 - ₱500',
      required_docs: ['2 Valid Government IDs', 'Cedula', 'Lease Contract / Proof of Address'],
      sub_steps: [
        { id: `${prefix}-brgy-1`, title: 'Get the Barangay Business Permit application form', completed: false },
        { id: `${prefix}-brgy-2`, title: 'Present 2 valid IDs, Cedula and proof of address', completed: false },
        { id: `${prefix}-brgy-3`, title: 'Pay the clearance fee set by your LGU ordinance', completed: false },
        { id: `${prefix}-brgy-4`, title: 'Claim the signed clearance with the official dry seal', completed: false },
      ],
    },
    {
      title: 'DTI Business Name Registration',
      category: 'Permits',
      status: 'Pending',
      desc: `Registers your ${trade} name nationwide for 5 years.`,
      agency: 'Department of Trade and Industry (DTI BNRS)',
      legal_basis: 'Act No. 3883 (Philippine Business Name Law)',
      estimated_time: '30 - 60 Minutes (Online)',
      estimated_cost: '₱530 (City/Municipal scope + doc stamp)',
      required_docs: ['1 Valid Government ID', 'DTI BNRS Online Application'],
      sub_steps: [
        { id: `${prefix}-dti-1`, title: 'Open the official DTI BNRS portal at bnrs.dti.gov.ph', completed: false },
        { id: `${prefix}-dti-2`, title: 'Check that your chosen name is still available', completed: false },
        { id: `${prefix}-dti-3`, title: 'Choose City/Municipal scope and pay via GCash or Maya', completed: false },
        { id: `${prefix}-dti-4`, title: 'Download and print your DTI certificate', completed: false },
      ],
    },
  ];

  if (!options.skipMayor) {
    steps.push({
      title: "Mayor's Business Permit & Fire Safety",
      category: 'Permits',
      status: 'Pending',
      desc: `City Hall permit authorising your ${trade} to operate in your municipality.`,
      agency: 'City / Municipal Hall BPLO & Bureau of Fire Protection',
      legal_basis: 'RA 7160 Local Government Code (Sec 143/151)',
      estimated_time: '3 - 7 Business Days',
      estimated_cost: '₱1,500 - ₱4,000',
      required_docs: ['DTI Certificate', 'Barangay Clearance', 'BFP Fire Safety Cert', 'Zoning Clearance'],
      sub_steps: [
        { id: `${prefix}-mayor-1`, title: 'Submit your DTI certificate and Barangay clearance to the BPLO', completed: false },
        { id: `${prefix}-mayor-2`, title: 'Pass the BFP fire safety inspection', completed: false },
        { id: `${prefix}-mayor-3`, title: 'Pay permit, garbage and sanitary fees at the Treasurer', completed: false },
        { id: `${prefix}-mayor-4`, title: "Claim your Mayor's Permit and business plate", completed: false },
      ],
    });
  }

  steps.push({
    title: 'BIR Registration & Official Receipts',
    category: 'Permits',
    status: 'Pending',
    desc: 'Tax registration so you can legally issue receipts.',
    agency: 'Bureau of Internal Revenue (Revenue District Office)',
    legal_basis: 'NIRC Sec 236 & RR 11-2018',
    estimated_time: '3 - 5 Business Days',
    estimated_cost: '₱530 ARF + ~₱1,000 receipt printing',
    required_docs: ['BIR Form 1901', 'DTI Certificate', 'Barangay Clearance', '2 Valid IDs'],
    sub_steps: [
      { id: `${prefix}-bir-1`, title: 'File BIR Form 1901 at your assigned RDO', completed: false },
      { id: `${prefix}-bir-2`, title: 'Pay the ₱500 Annual Registration Fee and ₱30 doc stamp', completed: false },
      { id: `${prefix}-bir-3`, title: 'Register your books of accounts', completed: false },
      { id: `${prefix}-bir-4`, title: 'Apply for Authority to Print and claim BIR Form 2303', completed: false },
    ],
  });

  if (options.sanitary) {
    steps.push({
      title: 'Sanitary Permit & Health Cards',
      category: 'Permits',
      status: 'Pending',
      desc: 'Required before anyone handles food for sale.',
      agency: 'City Health Office',
      legal_basis: 'PD 856 Sanitation Code of the Philippines',
      estimated_time: '2 - 4 Business Days',
      estimated_cost: '₱300 - ₱800 per person',
      required_docs: ['Medical Exam Results', 'Stool & Sputum Test', '1x1 Photos'],
      sub_steps: [
        { id: `${prefix}-san-1`, title: 'Book medical exams for everyone who will handle food', completed: false },
        { id: `${prefix}-san-2`, title: 'Submit results to the City Health Office', completed: false },
        { id: `${prefix}-san-3`, title: 'Attend the required food handling seminar', completed: false },
        { id: `${prefix}-san-4`, title: 'Claim health cards and display the sanitary permit', completed: false },
      ],
    });
  }

  return steps;
};

