/** Narrows the catalogue by category chip and free-text search. */
export const filterTemplates = (
  templates: StartupTemplate[],
  search: string,
  category: TemplateCategory | null
): StartupTemplate[] => {
  const query = search.trim().toLowerCase();

  return templates.filter((template) => {
    if (category && template.category !== category) return false;
    if (!query) return true;

    // Task titles are searched too, so "GCash" or "sanitary" finds the
    // template that actually covers it, not just ones naming it up front.
    return (
      template.title.toLowerCase().includes(query) ||
      template.desc.toLowerCase().includes(query) ||
      template.category.toLowerCase().includes(query) ||
      template.tasks.some((task) => task.title.toLowerCase().includes(query))
    );
  });
};
